FUNCTION CountUsableSubLibraries(deps, universe):
    total <- 1
    FOR EACH component IN WeaklyConnectedComponents(deps, universe):
        total <- total * CountClosedSubsetsOfComponent(deps, component)
    RETURN total
    // correctness: independent parts multiply, by an exact bijection
    //   s  |-->  (s intersect A, s intersect B)
    //   (p, q)  |-->  p union q

FUNCTION CountClosedSubsetsOfComponent(deps, comp):
    FOR EACH i IN comp:
        reach(i) <- all items of comp reachable from i along deps
    ideals <- { empty set }
    FOR EACH i IN comp, in a fixed order:
        ideals <- ideals  union  { s union reach(i) : s IN ideals }
    RETURN |ideals|
    // sanity brackets: 2^n if deps is empty, n+1 for a chain, n+1 < 2^n for n >= 2

FUNCTION ModularityIndex(deps, universe):
    RETURN log2(CountUsableSubLibraries(deps, universe)) / |universe|

