"""Algorithm: exact count of usable sub-libraries (dependency-closed subsets)."""

from __future__ import annotations

from typing import Dict, Iterable, List, Set, Tuple

Item = int
Deps = Dict[Item, Set[Item]]


def weakly_connected_components(deps: Deps, universe: Iterable[Item]) -> List[Set[Item]]:
    """Split the universe into parts with no dependency crossing between them."""
    us = set(universe)
    nbr: Dict[Item, Set[Item]] = {i: set() for i in us}
    for i in us:
        for j in deps.get(i, set()) & us:
            nbr[i].add(j)
            nbr[j].add(i)
    seen: Set[Item] = set()
    comps: List[Set[Item]] = []
    for i in us:
        if i in seen:
            continue
        stack, comp = [i], set()
        seen.add(i)
        while stack:
            x = stack.pop()
            comp.add(x)
            for y in nbr[x] - seen:
                seen.add(y)
                stack.append(y)
        comps.append(comp)
    return comps


def count_closed_subsets_component(deps: Deps, comp: Set[Item]) -> int:
    """Count dependency-closed subsets of one connected component.

    Reachability makes the dependency relation a preorder; a dependency-closed
    subset is exactly a downward-closed set (an order ideal) for it.  We count
    ideals by incremental insertion over a fixed order of the items: maintaining
    the family of ideals as a set of frozensets, each new item either stays out
    or is added together with everything it reaches.

    Exponential in the worst case -- unavoidably so, since a fully independent
    component of n items has 2^n ideals -- but linear in the OUTPUT size.
    """
    reach: Dict[Item, Set[Item]] = {}
    for i in comp:
        seen, stack = {i}, [i]
        while stack:
            x = stack.pop()
            for y in deps.get(x, set()) & comp:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        reach[i] = seen

    ideals: Set[frozenset] = {frozenset()}
    for i in sorted(comp):
        new: Set[frozenset] = set()
        for s in ideals:
            new.add(s)
            new.add(frozenset(s | reach[i]))
        ideals = new
    return len(ideals)


def count_usable_sublibraries(deps: Deps, universe: Iterable[Item]) -> int:
    """Exact number of dependency-closed subsets of the universe.

    Independent parts multiply exactly (a bijection, not an estimate), so the
    global count is the product over weakly connected components.  Sanity
    brackets: a fully independent family of n items gives 2^n, a chain of n
    items gives n + 1, and n + 1 < 2^n for every n >= 2.
    """
    total = 1
    for comp in weakly_connected_components(deps, universe):
        total *= count_closed_subsets_component(deps, comp)
    return total


def modularity_index(deps: Deps, universe: Iterable[Item]) -> float:
    """Where a library sits between monolith (n+1) and fully modular (2^n).

    Returns log2(count) / n, which is 1 for a fully independent family and
    tends to 0 for a chain.
    """
    import math

    n = len(set(universe))
    if n == 0:
        return 1.0
    return math.log2(count_usable_sublibraries(deps, universe)) / n


if __name__ == "__main__":
    n = 8
    free: Deps = {i: set() for i in range(n)}
    chain: Deps = {i: (set() if i == 0 else {i - 1}) for i in range(n)}
    mixed: Deps = {0: set(), 1: {0}, 2: {1}, 3: set(), 4: {3}, 5: set(), 6: set(), 7: set()}
    for name, d in (("free", free), ("chain", chain), ("mixed", mixed)):
        print(f"{name:6s} count = {count_usable_sublibraries(d, range(n)):4d}"
              f"   modularity index = {modularity_index(d, range(n)):.3f}")
